package com.privacyguardian.config; import com.privacyguardian.entity.User;import com.privacyguardian.repo.UserRepository;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataSeeder{@Bean CommandLineRunner seed(UserRepository r,PasswordEncoder e){return args->{if(!r.existsByUsername("admin")){User u=new User();u.setUsername("admin");u.setEmail("admin@privacyguardian.local");u.setPasswordHash(e.encode("admin123"));u.setRole("ADMIN");r.save(u);}if(!r.existsByUsername("user")){User u=new User();u.setUsername("user");u.setEmail("user@privacyguardian.local");u.setPasswordHash(e.encode("user123"));u.setRole("USER");r.save(u);}};}}
